def transform(grid):
    h, w = len(grid), len(grid[0])
    mid = next(c for c in range(w) if len({row[c] for row in grid}) == 1)
    left = [row[:mid] for row in grid]
    right = [row[mid+1:] for row in grid]

    def common_color(part):
        counts = {}
        for row in part:
            for x in row:
                counts[x] = counts.get(x, 0) + 1
        return max(counts, key=counts.get)

    left_bg = common_color(left)
    left_rare = next(x for row in left for x in row if x != left_bg)
    right_bg = common_color(right)
    right_rare = next(x for row in right for x in row if x != right_bg)

    return [[3 if left[r][c] == left_rare and right[r][c] == right_bg else right_bg
             for c in range(len(left[0]))] for r in range(h)]
